using System.Globalization;
using System.Text.Json;
using Api.Nutrition;

namespace Api.Tests;

/// <summary>
/// The C# implementation of Step 1 has to match the Python reference, number
/// for number.
///
/// <para>The cases live in <c>data/buoc1_cases.json</c>, generated by
/// <c>tools/gen_buoc1_cases.py</c>. The reference implementation in that file
/// was written afresh from <c>docs/SYSTEM_ARCHITECTURE.md</c> §3.1 and is
/// <b>not</b> copied from this class — copying it would only confirm that the
/// two are wrong in the same way.</para>
///
/// <para>This suite needs NO database and NO server: the
/// <see cref="NutritionTargets"/> class is pure functions over numbers. The
/// part that needs a database is handled by
/// <c>tools/smoke_backend.py</c>.</para>
///
/// <para>Note on language: the three keys <c>ten</c> / <c>vao</c> / <c>ra</c>
/// read below are the fixture file's own keys, and
/// <c>mobile/test/buoc1_parity_test.dart</c> reads the same three out of the
/// same file. Renaming them means changing the generator, this file and the
/// Dart test in one go, so they stay as they are until that can be done
/// together. The class and file name are held back for the same reason — the
/// Dart test's header names this path.</para>
/// </summary>
public class Buoc1ParityTests
{
    private static readonly JsonDocument Fixture = LoadFixture();

    private static JsonDocument LoadFixture()
    {
        // Walk up from the run directory to the repository root.
        // `AppContext.BaseDirectory` sits deep inside bin/Debug/netX, and
        // that depth changes with the build configuration — so the root is
        // found by a MARKER (a `db` directory holding `db/schema.sql`) rather
        // than by counting levels.
        var d = new DirectoryInfo(AppContext.BaseDirectory);
        while (d is not null
               && !File.Exists(Path.Combine(d.FullName, "db", "schema.sql")))
        {
            d = d.Parent;
        }
        if (d is null)
        {
            throw new InvalidOperationException(
                "Could not find the repository root (marker: db/schema.sql) "
                + "from " + AppContext.BaseDirectory);
        }

        var file = Path.Combine(d.FullName, "data", "buoc1_cases.json");
        if (!File.Exists(file))
        {
            throw new FileNotFoundException(
                $"{file} is missing. Generate it with: "
                + "python tools/gen_buoc1_cases.py");
        }
        return JsonDocument.Parse(File.ReadAllText(file));
    }

    public static TheoryData<string> CaseNames()
    {
        var names = new TheoryData<string>();
        foreach (var c in
                 Fixture.RootElement.GetProperty("cases").EnumerateArray())
        {
            names.Add(c.GetProperty("ten").GetString()!);
        }
        return names;
    }

    private static JsonElement Case(string name)
        => Fixture.RootElement.GetProperty("cases").EnumerateArray()
            .First(c => c.GetProperty("ten").GetString() == name);

    /// <summary>Rounds away from zero, like the Python and the Dart
    /// implementations.</summary>
    private static decimal Round(decimal v, int places = 0)
        => Math.Round(v, places, MidpointRounding.AwayFromZero);

    [Theory]
    [MemberData(nameof(CaseNames))]
    public void Matches_the_reference(string name)
    {
        var item = Case(name);
        var input = item.GetProperty("vao");
        var expected = item.GetProperty("ra");

        var gender = input.GetProperty("gender").GetString()!;
        var heightCm = input.GetProperty("heightCm").GetDecimal();
        var weightKg = input.GetProperty("weightKg").GetDecimal();
        var dateOfBirth = DateOnly.Parse(
            input.GetProperty("dateOfBirth").GetString()!,
            CultureInfo.InvariantCulture);
        var today = DateOnly.Parse(
            input.GetProperty("today").GetString()!,
            CultureInfo.InvariantCulture);

        var result = NutritionTargets.Compute(
            gender,
            dateOfBirth,
            heightCm,
            weightKg,
            input.GetProperty("activityLevel").GetString()!,
            input.GetProperty("goal").GetString()!,
            (byte)input.GetProperty("proteinPct").GetInt32(),
            (byte)input.GetProperty("carbsPct").GetInt32(),
            (byte)input.GetProperty("fatPct").GetInt32(),
            today);

        Assert.Equal(expected.GetProperty("age").GetInt32(), result.Age);
        Assert.Equal(expected.GetProperty("bmi").GetDecimal(),
                     Round(result.Bmi, 2));
        Assert.Equal(expected.GetProperty("bmiCategory").GetString(),
                     result.BmiCategory);
        Assert.Equal(expected.GetProperty("bmrKcal").GetDecimal(),
                     Round(result.BmrKcal));
        Assert.Equal(expected.GetProperty("tdeeKcal").GetDecimal(),
                     Round(result.TdeeKcal));
        Assert.Equal(expected.GetProperty("activityFactor").GetDecimal(),
                     result.ActivityFactorValue);
        Assert.Equal(expected.GetProperty("dailyCaloriesTarget").GetDecimal(),
                     Round(result.DailyCaloriesTarget));
        Assert.Equal(expected.GetProperty("goalAdjustmentKcal").GetDecimal(),
                     Round(result.GoalAdjustmentKcal));
        Assert.Equal(expected.GetProperty("proteinG").GetDecimal(),
                     Round(result.ProteinG, 1));
        Assert.Equal(expected.GetProperty("carbsG").GetDecimal(),
                     Round(result.CarbsG, 1));
        Assert.Equal(expected.GetProperty("fatG").GetDecimal(),
                     Round(result.FatG, 1));

        var meals = result.MealDistribution()
            .ToDictionary(m => m.MealType, m => Round(m.Kcal));
        foreach (var kv in expected.GetProperty("mealKcal").EnumerateObject())
        {
            Assert.Equal(kv.Value.GetDecimal(), meals[kv.Name]);
        }
    }

    /// <summary>
    /// The activity factors and the meal shares have to match the tables in
    /// the fixture file, in both directions — adding an activity level on one
    /// side and forgetting the other would leave every existing case passing.
    /// </summary>
    [Fact]
    public void Factor_tables_match_both_ways()
    {
        var factors = Fixture.RootElement.GetProperty("activityFactor");
        Assert.Equal(
            factors.EnumerateObject().Select(p => p.Name).OrderBy(x => x),
            NutritionTargets.ActivityFactor.Keys.OrderBy(x => x));
        foreach (var p in factors.EnumerateObject())
        {
            Assert.Equal(p.Value.GetDecimal(),
                         NutritionTargets.ActivityFactor[p.Name]);
        }

        var shares = Fixture.RootElement.GetProperty("mealShare");
        Assert.Equal(
            shares.EnumerateObject().Select(p => p.Name).OrderBy(x => x),
            NutritionTargets.MealShare.Keys.OrderBy(x => x));
        foreach (var p in shares.EnumerateObject())
        {
            Assert.Equal(p.Value.GetDecimal(),
                         NutritionTargets.MealShare[p.Name]);
        }

        // The four meal shares have to add up to exactly 1. A set adding up
        // to 0.95 causes no error at all — Step 4 would simply allocate 5 %
        // less energy every day.
        Assert.Equal(1.000m, NutritionTargets.MealShare.Values.Sum());
    }

    /// <summary>
    /// A value outside the ENUM has to THROW, never return a number.
    ///
    /// <para>Returning a default would mean a misspelled string — `"Male"`
    /// instead of `"male"` — produces a plausible-looking target, computed
    /// with another group's constant.</para>
    /// </summary>
    [Theory]
    [InlineData("Male")]
    [InlineData("nam")]
    [InlineData("")]
    public void Gender_outside_the_enum_throws(string gender)
        => Assert.Throws<ArgumentOutOfRangeException>(
            () => NutritionTargets.Bmr(gender, 68.5m, 172m, 22));

    [Theory]
    [InlineData("Moderate")]
    [InlineData("veryactive")]
    public void Activity_level_outside_the_enum_throws(string v)
        => Assert.Throws<ArgumentOutOfRangeException>(
            () => NutritionTargets.Tdee(1655m, v));

    [Theory]
    [InlineData("lose")]
    [InlineData("maintain_weight")]
    public void Goal_outside_the_enum_throws(string m)
        => Assert.Throws<ArgumentOutOfRangeException>(
            () => NutritionTargets.EnergyTarget(2565m, 1655m, m));

    /// <summary>
    /// Three macro percentages that do not add up to 100 % have to throw
    /// rather than silently allocate too little energy — `chk_macro_sum` in
    /// the schema holds the same invariant.
    /// </summary>
    [Theory]
    [InlineData(15, 60, 24)]
    [InlineData(15, 60, 26)]
    [InlineData(0, 0, 0)]
    public void Macros_not_summing_to_100_throw(int p, int c, int f)
        => Assert.Throws<ArgumentException>(() => NutritionTargets.Compute(
            "male", new DateOnly(2004, 1, 1), 172m, 68.5m,
            "moderate", "maintain", (byte)p, (byte)c, (byte)f,
            new DateOnly(2026, 11, 8)));

    /// <summary>
    /// `lose_weight` never produces a target below the BMR, at any activity
    /// level — eating less than the basal metabolic rate is not a weight-loss
    /// plan.
    /// </summary>
    [Fact]
    public void Losing_weight_never_goes_below_bmr()
    {
        foreach (var v in NutritionTargets.ActivityFactor.Keys)
        {
            foreach (var g in new[] { "male", "female", "other" })
            {
                var bmr = NutritionTargets.Bmr(g, 45m, 150m, 60);
                var tdee = NutritionTargets.Tdee(bmr, v);
                var target = NutritionTargets.EnergyTarget(
                    tdee, bmr, "lose_weight");
                Assert.True(target >= bmr,
                            $"{g}/{v}: target {target} is below the BMR {bmr}");
            }
        }
    }
}
